//! Data types of the API. They are serialised as JSON and mirrored to TypeScript by `ts-rs`
//! (`ui/src/lib/api/bindings.ts`, regenerated by `scripts/gen-bindings.sh`).

use notatnik_core::{BlockOp, TaskState};
use serde::{Deserialize, Serialize};
use ts_rs::TS;

/// Inline content of a block, ready to render without `innerHTML`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum Inline {
    /// Plain text (raw HTML ends up here, shown literally).
    Text { text: String },
    /// `**bold**`
    Bold { children: Vec<Inline> },
    /// `*italic*`
    Italic { children: Vec<Inline> },
    /// `~~strike~~`
    Strike { children: Vec<Inline> },
    /// `==highlight==`
    Highlight { children: Vec<Inline> },
    /// `` `code` ``
    Code { text: String },
    /// External link (only http, https and mailto survive).
    Link { href: String, children: Vec<Inline> },
    /// Image; `local` images are relative paths below the graph (e.g. `../assets/x.png`).
    Image {
        src: String,
        alt: String,
        local: bool,
    },
    /// `[[page]]` / `[[page|label]]`
    PageRef {
        target: String,
        label: Option<Vec<Inline>>,
    },
    /// `#tag`
    Tag { target: String },
    /// `((id))`
    BlockRef { uid: String },
    /// `!((id))`
    BlockEmbed { uid: String },
    /// `![[page]]`
    PageEmbed { target: String },
    /// `[^label]`
    FootnoteRef { label: String },
    /// A line break inside a paragraph.
    SoftBreak,
    /// A hard line break.
    HardBreak,
}

/// Block-level content of a block.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum Node {
    /// A paragraph.
    Paragraph { children: Vec<Inline> },
    /// `## Heading`
    Heading { level: u8, children: Vec<Inline> },
    /// A fenced or indented code block.
    CodeBlock { lang: Option<String>, code: String },
    /// A GFM table.
    Table {
        aligns: Vec<String>,
        header: Vec<Vec<Inline>>,
        rows: Vec<Vec<Vec<Inline>>>,
    },
    /// `> quote`
    Quote { children: Vec<Node> },
    /// A Markdown list inside a block.
    List {
        ordered: bool,
        items: Vec<Vec<Node>>,
    },
    /// `---`
    Rule,
    /// A fenced block with the language `query`.
    Query { text: String },
    /// `::: info` ... `:::` (written by Nextcloud Text and others); `kind` is the lowercase word after the colons.
    Callout { kind: String, children: Vec<Node> },
    /// `<details><summary>..</summary>..</details>`.
    Details {
        summary: Vec<Inline>,
        open: bool,
        children: Vec<Node>,
    },
    /// `[^label]: text`
    Footnote { label: String, children: Vec<Node> },
}

/// A block property for display.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct PropView {
    /// Key.
    pub key: String,
    /// Raw value text.
    pub raw: String,
    /// `text`, `number`, `bool`, `date`, `datetime`, `link` or `list`.
    pub kind: String,
    /// Page names, for link values.
    pub links: Vec<String>,
    /// Hidden in the rendered view (system or configured).
    pub hidden: bool,
}

/// Task data of a block.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct TaskView {
    /// State.
    pub state: TaskState,
    /// `scheduled::` as text.
    pub scheduled: Option<String>,
    /// `deadline::` as text.
    pub deadline: Option<String>,
    /// The priority label as written in the file (`A`, `B`, `C` by default).
    pub priority: Option<String>,
    /// Its rank: 0 is the most important.
    pub priority_rank: Option<u32>,
    /// `repeat::` as text.
    pub repeat: Option<String>,
    /// The task is part of a chain of follow-ups (`follows::`), see `task_chain`.
    pub chain: bool,
    /// Written as a Markdown checkbox (`[ ]`, `[x]`): the marker then toggles between open and done.
    pub checkbox: bool,
}

/// `task_chain`
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
pub struct ChainArgs {
    /// Page name.
    pub page: String,
    /// Block path.
    pub path: Vec<u32>,
}

/// One task of a chain.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct ChainItem {
    /// The block ID, if it has one.
    pub uid: Option<String>,
    /// The task it followed is gone (a `follows::` target that does not exist).
    pub missing: bool,
    /// Page name.
    pub page: String,
    /// Block path.
    pub path: Vec<u32>,
    /// First line of the block.
    pub text: String,
    /// `TODO`, `DONE`, ...
    pub state: Option<String>,
    /// Scheduled date.
    pub scheduled: Option<String>,
    /// Deadline.
    pub deadline: Option<String>,
    /// Nesting: 0 for the first task, 1 for the follow-up, ...; branches are deeper.
    pub depth: u32,
}

/// The chain a task is in.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct ChainView {
    /// Every task of the chain, in order.
    pub items: Vec<ChainItem>,
    /// Index of the asked-for task in `items`.
    pub position: u32,
}

/// One block of a page.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct BlockView {
    /// Runtime ID, stable across edits and external changes within the session (P1.26).
    pub id: u32,
    /// Child-index path from the page root.
    pub path: Vec<u32>,
    /// Content hash of the block's own text (stale-edit guard).
    pub hash: String,
    /// `^id`, if the block has one.
    pub uid: Option<String>,
    /// Raw Markdown for the editor (first line, properties, continuation lines; no bullet, indentation or `^id`).
    pub text: String,
    /// Rendered content (without task marker, properties and `^id`).
    pub content: Vec<Node>,
    /// Task data.
    pub task: Option<TaskView>,
    /// Progress notes from the `:LOGBOOK:` drawer, in file order.
    pub logbook: Vec<LogEntryView>,
    /// Properties.
    pub props: Vec<PropView>,
    /// Text between bullets (a heading, a table, a code block ...), not a bullet: no bullet dot, no nesting,
    /// Enter adds a line, edited as raw Markdown.
    pub plain: bool,
    /// Collapsed on this device.
    pub collapsed: bool,
    /// Children.
    pub children: Vec<BlockView>,
}

/// One line of a task's logbook.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct LogEntryView {
    /// `YYYY-MM-DD` or `YYYY-MM-DD HH:MM`; empty for a line without a date.
    pub when: String,
    /// The note as written.
    pub text: String,
    /// The note rendered (links, tags, emphasis ...).
    pub content: Vec<Node>,
}

