/// A page ready to render.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct PageView {
    /// Canonical page name.
    pub name: String,
    /// Display title (frontmatter title or the name).
    pub title: String,
    /// File path relative to the graph, `None` only for display of unknown pages.
    pub path: String,
    /// Whether the file exists (a missing page is shown empty and created on first content).
    pub exists: bool,
    /// Journal page.
    pub is_journal: bool,
    /// Hash of the file content; pass it back as `base_hash`. `None` while the file doesn't exist.
    pub hash: Option<String>,
    /// Frontmatter.
    pub frontmatter: Option<FrontmatterView>,
    /// Text before the first bullet.
    pub preamble: Option<BlockView>,
    /// Top-level blocks.
    pub blocks: Vec<BlockView>,
    /// Direct child pages in the namespace tree.
    pub child_pages: Vec<String>,
    /// Parse problems.
    pub diagnostics: Vec<DiagnosticView>,
}

