pub struct FolderItem {
    pub name: String,
    /// `<server>/f/<id>` on Nextcloud (opens the folder in its Files app), else the folder's own address.
    pub link: String,
    /// The link is the folder's address, which breaks when the folder is renamed or moved.
    pub by_path: bool,
}

/// `file_browse` result.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct FileBrowse {
    /// The folder that was listed, cleaned (`Notes/Work`).
    pub path: String,
    pub exists: bool,
    /// Sorted without regard to case; hidden ones left out.
    pub folders: Vec<FolderItem>,
    pub files: Vec<FileItem>,
    /// The link for the top of the source ("All files").
    pub root: FolderItem,
}

/// `webdav_browse` result: the folders directly inside a folder of the server.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
pub struct WebdavFolders {
    /// The folder that was listed, written the way `folder` is (`Notes/graph`; empty for the account's files).
    pub folder: String,
    /// It exists (a folder that does not is a new one: the list is empty).
    pub exists: bool,
    /// Names of the folders inside, sorted, without the hidden ones.
    pub folders: Vec<String>,
    /// How many items (files and folders) are inside.
    pub items: u32,
    /// It holds a Notatnik graph.
    pub has_graph: bool,
}

/// `webdav_test` result.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
pub struct WebdavTest {
    /// The address of the folder that was looked at.
    pub url: String,
    /// The folder exists.
    pub exists: bool,
    /// How many items are directly in it.
    pub items: u32,
    /// It holds a Notatnik graph (a `.notatnik`, `pages` or `journals` folder).
    pub has_graph: bool,
}

/// A calendar of the account.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
pub struct CalendarView {
    /// Its address on the server; the key the settings keep.
    pub href: String,
    pub name: String,
    /// It takes tasks (VTODO).
    pub tasks: bool,
    /// It takes events (VEVENT).
    pub events: bool,
}

/// The login the calendar sync uses.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
pub struct CalendarAccountView {
    pub server: String,
    pub user: String,
    /// A login of its own; false means the login of the graph's sync.
    pub own: bool,
}

/// `calendar_status` result: the calendar settings of the open graph.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
pub struct CalendarStatus {
    /// The login that would be used; none when the graph has no sync and no login of its own was given.
    pub account: Option<CalendarAccountView>,
    pub enabled: bool,
    /// Calendars to read events from.
    pub read: Vec<String>,
    /// The calendar that receives the tasks.
    pub tasks: Option<String>,
    /// `vtodo` or `vevent` (the graph's `[calendar]` section).
    pub tasks_as: String,
    /// `complete` or `delete` (the graph's `[calendar]` section).
    pub on_delete: String,
    /// Tasks created in other apps are copied into the inbox page (`[calendar] import = "inbox"`).
    pub import_tasks: bool,
    /// The page they go to.
    pub inbox: String,
}

/// `calendar_connect` arguments: all empty uses the login of the graph's sync.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
pub struct CalendarConnectArgs {
    pub server: Option<String>,
    pub user: Option<String>,
    pub password: Option<String>,
}

/// `calendar_connect` result.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
pub struct CalendarList {
    pub account: CalendarAccountView,
    pub calendars: Vec<CalendarView>,
}

/// `calendar_save` arguments.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
pub struct CalendarSaveArgs {
    pub enabled: bool,
    pub read: Vec<String>,
    pub tasks: Option<String>,
    /// Copy tasks created in other apps into the inbox page.
    pub import_tasks: bool,
}

/// `calendar_events` arguments: the days to show, `YYYY-MM-DD`, both included.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
pub struct CalendarEventsArgs {
    pub from: String,
    pub to: String,
}

/// An event on a stretch of days (JR-5).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
pub struct CalendarEventView {
    pub uid: String,
    pub title: String,
    /// First day, `YYYY-MM-DD`, in local time.
    pub date: String,
    /// Last day; the same as `date` for most events.
    pub end_date: String,
    /// `HH:MM`; none for an all-day event.
    pub start: Option<String>,
    pub end: Option<String>,
    pub location: Option<String>,
    /// The calendar it comes from.
    pub calendar: String,
}

/// One line of the calendar sync log (CA-8).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
pub struct CalendarLogEntry {
    /// When, `YYYY-MM-DDTHH:MM` local time.
    pub at: String,
    /// `pulled`, `conflict`, `title_kept`, `removed_in_calendar`.
    pub kind: String,
    pub uid: String,
    /// The task's title in the notes.
    pub title: String,
    pub page: String,
    /// The field (`status`, `scheduled`, `deadline`, `priority`, `title`, `repeat`).
    pub field: Option<String>,
    pub local: Option<String>,
    pub remote: Option<String>,
    /// `local` or `remote`: the value that was kept.
    pub winner: Option<String>,
}

/// `calendar_use_other_value` arguments: the conflict in the sync log to turn around.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
pub struct CalendarUseOtherArgs {
    pub uid: String,
    /// The log entry's field (`status`, `scheduled`, `deadline`, `priority`, `title`, `repeat`).
    pub field: String,
}

/// `calendar_sync` result.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize, TS)]
pub struct CalendarSyncReport {
    /// Tasks sent for the first time.
    pub created: u32,
    /// Tasks whose calendar item was changed.
    pub updated: u32,
    /// Tasks that were already in the calendar as they are.
    pub unchanged: u32,
    /// Items marked completed because their task is gone.
    pub retired: u32,
    /// Items deleted because their task is gone.
    pub deleted: u32,
    /// Tasks whose calendar item was changed elsewhere and was not overwritten.
    pub conflicts: Vec<String>,
    /// Dated tasks that had no block ID and were given one (`^abc123` was added to their line).
    pub ids_added: u32,
    /// Event resources that were new, changed or deleted in the calendars read for events.
    pub events_changed: u32,
    /// Tasks created in other apps that were copied into the inbox page.
    pub imported: u32,
    /// Tasks of the notes that took a change from the calendar.
    pub pulled: u32,
    /// Tasks that were deleted in the calendar; their blocks stay.
    pub removed_in_calendar: u32,
    /// Entries added to the sync log (conflicts, changes that could not be written, deletions).
    pub logged: u32,
}
